<script lang="ts">import {page} from '$app/state';import {API} from '$lib/config';import {bearer,request} from '$lib/session.svelte';import {signIn} from '$lib/oidc';const token=$derived(page.params.token??'');let invitation=$state<any>();let error=$state('');let accepted=$state<any>();$effect(()=>{token;void load()});async function load(){const response=await fetch(`${API}/v1/invitations/${encodeURIComponent(token)}/validate`);if(response.ok)invitation=await response.json();else error='This invitation is invalid, expired, or already used.'}async function accept(){if(!await bearer()){await signIn(page.url.pathname);return}try{accepted=await request(`/v1/invitations/${encodeURIComponent(token)}/accept`,{method:'POST'});}catch(e){error=e instanceof Error?e.message:String(e)}}</script><main class="shell"><div class="card" style="max-width:520px;margin:10vh auto">{#if accepted}<h1>Welcome</h1><p>Your {accepted.workshop_id} access is being prepared.</p><a class="button" href={`/workshops/${accepted.workshop_id}/members`}>Open workshop</a>{:else if invitation}<h1>Join {invitation.workshop_name}</h1><p>You were invited as <strong>{invitation.role.replace('_',' ')}</strong> using {invitation.email}.</p><button onclick={accept}>Sign in and accept</button>{:else if error}<p class="error">{error}</p>{:else}<p>Checking invitation…</p>{/if}</div></main>
